// Agrega los informes de ayer por línea y arma el correo del resumen diario.
const ayer = $now.setZone('Europe/Madrid').minus({ days: 1 }).toFormat('yyyy-MM-dd');
const filas = $input.all().map((i) => i.json).filter((r) => r.linea);
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const pct = (n) => `${String(Math.round(n * 10) / 10).replace('.', ',')} %`;
const fmt = (n) => Number(n).toLocaleString('es-ES');

if (filas.length === 0) {
  return [{ json: {
    asunto: `Resumen de turnos ${ayer}: sin informes`,
    html: `<p style="font-family:Arial,sans-serif">Ayer (${ayer}) no se registró ningún informe de turno. Revisa si los operarios rellenaron el formulario.</p>`,
  } }];
}

const lineas = {};
for (const r of filas) {
  const l = (lineas[r.linea] ??= { metros: 0, objetivo: 0, turnos: 0, avisos: 0, paradas: 0 });
  l.metros += Number(r.metros);
  l.objetivo += Number(r.objetivo);
  l.turnos += 1;
  l.avisos += r.aviso ? 1 : 0;
  l.paradas += Number(r.paradas_total);
}
const totalMetros = filas.reduce((a, r) => a + Number(r.metros), 0);
const totalObjetivo = filas.reduce((a, r) => a + Number(r.objetivo), 0);
const eficiencia = (totalMetros / totalObjetivo) * 100;
const avisos = filas.filter((r) => r.aviso).length;

const motivos = { parada_averia: 'Avería', parada_cambio_formato: 'Cambio de formato', parada_falta_material: 'Falta de material', parada_otros: 'Otros' };
const paradas = filas.flatMap((r) => Object.entries(motivos).map(([k, nombre]) => ({ linea: r.linea, turno: r.turno, nombre, min: Number(r[k]) })))
  .filter((p) => p.min > 0)
  .sort((a, b) => b.min - a.min)
  .slice(0, 3);

const td = 'style="padding:4px 10px;border-bottom:1px solid #eee"';
const filasLinea = Object.entries(lineas).sort().map(([nombre, l]) => {
  const ef = (l.metros / l.objetivo) * 100;
  return `<tr><td ${td}>${esc(nombre)}</td><td ${td}>${l.turnos}</td><td ${td}>${fmt(l.metros)}</td><td style="padding:4px 10px;border-bottom:1px solid #eee;color:${ef < 80 ? '#b42318' : '#067647'}"><b>${pct(ef)}</b></td><td ${td}>${l.paradas} min</td><td ${td}>${l.avisos}</td></tr>`;
}).join('\n');

const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">
<p>Resumen de los turnos de ayer, <b>${ayer}</b>: ${filas.length} informes, eficiencia global <b>${pct(eficiencia)}</b>, ${avisos} ${avisos === 1 ? 'turno' : 'turnos'} por debajo del 80 %.</p>
<table style="border-collapse:collapse">
<tr style="text-align:left;color:#555"><th ${td}>Línea</th><th ${td}>Turnos</th><th ${td}>Metros</th><th ${td}>Eficiencia</th><th ${td}>Paradas</th><th ${td}>Avisos</th></tr>
${filasLinea}
</table>
<p style="margin-top:16px"><b>Paradas más largas</b></p>
<ol>${paradas.map((p) => `<li>${esc(p.linea)} · turno de ${esc(p.turno).toLowerCase()}: ${esc(p.nombre)}, ${p.min} min</li>`).join('')}</ol>
<p style="color:#888;font-size:12px">Informe de turno automático · n8n</p>
</div>`;

return [{ json: {
  asunto: `${avisos ? '⚠ ' : ''}Resumen de turnos ${ayer}: ${pct(eficiencia)}${avisos ? ` · ${avisos} con aviso` : ''}`,
  html,
} }];
